const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];let chartVisible={pulse:true,spo2:true,temperature:true,steps:true};let token=localStorage.getItem('hh_token')||'',user=JSON.parse(localStorage.getItem('hh_user')||'null'),view='dashboard',days=7,cache={};const demo={patient:['patient@healthhub.local','patient123'],doctor:['doctor@healthhub.local','doctor123'],admin:['admin@healthhub.local','admin123']};
function toast(t){const e=$('#toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2300)}
async function api(path,opts={}){const r=await fetch('/api'+path,{...opts,headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{}),...(opts.headers||{})}});const data=await r.json().catch(()=>({}));if(!r.ok)throw Error(data.error||'Ошибка запроса');return data}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function money(v){return new Intl.NumberFormat('ru-RU').format(Number(v||0))}
function formatMetric(v){return v==null?'—':new Intl.NumberFormat('ru-RU',{maximumFractionDigits:1}).format(Number(v))}
function updateUnread(n){for(const id of ['header-unread','nav-unread']){const e=document.getElementById(id);if(e){e.textContent=n>99?'99+':String(n);e.hidden=!n}}}
function categoryIcon(c){return({'Питьевой режим':'💧','Питание':'🥗','Физическая активность':'👟','Сон и восстановление':'🌙','Обследования':'🩺','Личное':'✦'})[c]||'✦'}
function dateOnly(value){return new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Moscow',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(value))}
function toBase64(file){return new Promise((resolve,reject)=>{if(!file||!file.size)return resolve(null);const reader=new FileReader();reader.onload=()=>resolve({name:file.name,type:file.type,data:String(reader.result).split(',')[1]});reader.onerror=reject;reader.readAsDataURL(file)})}

function shell(){const links=[['dashboard','⌂','Главная'],['metrics','♥','Мои показатели'],['appointments','▣','Записи к врачу'],['labs','▤','Анализы'],['records','▧','Медкарта'],['notifications','♢','Уведомления'],['recommendations','✦','Рекомендации'],['assistant','✳','ИИ-ассистент'],['clinics','⌖','Клиники и карта'],['report','▥','Отчёты'],['settings','⚙','Настройки']];$('#root').innerHTML='<div class="layout"><aside class="sidebar"><div class="brand"><div class="logo">♥</div><span><b>HealthHub AI</b><small>Ваше здоровье — в фокусе</small></span></div><div class="nav-group">МЕДИЦИНСКИЙ КАБИНЕТ</div><nav class="nav">'+links.map(x=>'<button data-view="'+x[0]+'" class="'+(view===x[0]?'active':'')+'"><span class="ico">'+x[1]+'</span>'+x[2]+(x[0]==='notifications'?'<span class="nav-badge" id="nav-unread" hidden></span>':'')+'</button>').join('')+'</nav><div class="profile"><span class="avatar">'+esc((user?.name||'HH').split(' ').map(x=>x[0]).slice(0,2).join(''))+'</span><button class="profile-link" data-view="settings"><b>'+esc(user?.name)+'</b><small>'+roleName(user?.role)+'</small></button><button class="logout" id="logout" title="Выйти">⇥</button></div></aside><main class="main"><header class="topbar"><label class="searchbox">⌕ <input id="global-search" placeholder="Поиск по врачам, анализам, симптомам…"></label><div class="top-right"><span class="date-label">'+new Intl.DateTimeFormat('ru-RU',{dateStyle:'medium'}).format(new Date())+'</span><button class="bell" data-view="notifications" title="Уведомления">♧<span id="header-unread" class="notification-count" hidden></span></button><button class="icon-button" data-view="settings" title="Настройки">⚙</button><button class="book-btn" data-view="appointments"><span>▣</span> Записаться на приём</button></div></header><section class="workspace"><div id="view-root"></div></section><nav class="mobile-tabs"><button data-view="dashboard">⌂<small>Главная</small></button><button data-view="metrics">♥<small>История</small></button><button data-view="appointments">▣<small>Записи</small></button><button data-view="assistant">✳<small>Чат</small></button><button data-view="settings">♙<small>Профиль</small></button></nav></main></div><dialog id="action-dialog"></dialog><div id="toast" class="toast"></div>';$$('[data-view]').forEach(b=>b.onclick=()=>go(b.dataset.view));$('#logout').onclick=logout;$('#global-search').onkeydown=e=>{if(e.key==='Enter'&&e.target.value.trim()){sessionStorage.setItem('hh_search',e.target.value.trim());go('search')}};renderView()}
function roleName(r){return({patient:'Пациент',doctor:'Врач',admin:'Администратор'})[r]||''}
function go(v){view=v;renderView();$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v))}
function head(title,sub,action=''){return '<div class="page-head"><div><span class="eyebrow">HEALTHHUB AI · '+esc(roleName(user?.role).toUpperCase())+'</span><h1>'+title+'</h1><p>'+sub+'</p></div>'+action+'</div>'}
function button(label,act='primary',id=''){const content=label.startsWith('＋')?'<span class="add-icon" aria-hidden="true">+</span>'+label.slice(1):label;return '<button class="'+act+'" '+(id?'id="'+id+'"':'')+'>'+content+'</button>'}
function openForm(title,fields,onSave){const d=$('#action-dialog');d.innerHTML='<form method="dialog" class="action-dialog"><header><div><span class="eyebrow">HEALTHHUB AI</span><h2>'+esc(title)+'</h2></div><button type="button" class="dialog-x" aria-label="Закрыть">×</button></header><div class="dialog-fields form">'+fields+'</div><footer><button type="button" class="secondary" data-close>Отмена</button><button type="submit" class="primary"><span class="add-icon">✓</span>Сохранить</button></footer></form>';const form=d.querySelector('form');d.showModal();d.querySelector('[data-close]').onclick=()=>d.close();d.querySelector('.dialog-x').onclick=()=>d.close();form.onsubmit=async e=>{e.preventDefault();const submit=form.querySelector('[type=submit]');submit.disabled=true;try{await onSave(Object.fromEntries(new FormData(form)));d.close()}catch(err){toast(err.message)}finally{submit.disabled=false}}}
function localDateTime(value){const d=value?new Date(value):new Date(Date.now()+86400000);d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,16)}
async function renderView(){if(!token||!user){loginScreen();return}const root=$('#view-root');root.innerHTML='<div class="panel">Загружаю данные…</div>';try{const views={dashboard:dashboard,metrics:metricsView,appointments:appointmentsView,labs:labsView,records:recordsView,notifications:notificationsView,recommendations:recommendationsView,assistant:assistantView,clinics:clinicsView,report:reportView,settings:settingsView,search:searchView,doctors:doctorsView};root.innerHTML=await (views[view]||dashboard)();bindView()}catch(e){root.innerHTML=head('Не удалось загрузить раздел','Проверьте подключение к серверу')+'<div class="panel">'+esc(e.message)+'</div>';}}
async function dashboard(){if(user.role==='admin'){const d=await api('/admin/summary');return head('Панель администратора','Управление учётными записями, расписаниями и справочниками')+'<div class="grid metrics admin-metrics">'+[['Активные пользователи',d.users.reduce((n,x)=>n+x.count,0),'♙'],['Врачи',d.doctors,'✚'],['Клиники',d.clinics,'⌖'],['Записи на приём',d.appointments,'▣'],['Анализы',d.labs,'▤'],['Записи медкарты',d.records,'▧']].map(x=>'<article class="card metric"><div class="metric-top"><span>'+x[0]+'</span><span class="metric-icon">'+x[2]+'</span></div><strong>'+x[1]+'</strong><small>Сводные данные системы</small></article>').join('')+'</div><div class="grid lower-grid"><article class="panel"><h2>Управление системой</h2><p class="muted">Администратор управляет пользователями и клиниками. Доступа к содержимому медицинских записей по умолчанию нет.</p><button class="primary" data-view="settings">Открыть настройки</button></article><article class="panel"><h2>Рабочие разделы</h2><div class="toolbar"><button class="secondary" data-view="clinics">Клиники</button><button class="secondary" data-view="appointments">Расписания</button><button class="secondary" data-view="report">Сводные отчёты</button></div></article></div>'}const[d,allVisits,recs,clinics,analytics]=await Promise.all([api('/dashboard'),api('/appointments'),api('/recommendations'),api('/clinics'),api('/analytics?days='+days)]);cache.clinics=clinics;cache.recommendations=recs;updateUnread(d.unread||0);const lookup=Object.fromEntries(d.metrics.map(m=>[m.code,m]));const defs=[['pulse','♥','#fff0f0','Пульс'],['spo2','◉','#edf4ff','SpO₂'],['temperature','♨','#fff5e7','Температура'],['steps','👣','#e8f8f1','Шаги сегодня']];const visits=[...allVisits].sort((a,b)=>new Date(a.starts_at)-new Date(b.starts_at));const upcoming=visits.filter(a=>!['Завершена','Отменена'].includes(a.status)).slice(0,3);const recent=[...visits].sort((a,b)=>new Date(b.starts_at)-new Date(a.starts_at)).slice(0,4);const next=upcoming[0];const clinic=clinics[0];const recsHtml=recs.slice(0,3).map(r=>'<div class="mini-recommendation"><span class="line-icon">'+categoryIcon(r.category)+'</span><span><b>'+esc(r.title)+'</b><small>'+esc(r.category)+' · '+(r.due_date?new Date(r.due_date).toLocaleDateString('ru-RU'):'без срока')+'</small></span><span class="status">'+esc(r.status)+'</span></div>').join('');return head('Здравствуйте, '+esc(user.name.split(' ')[0])+' 👋','Ваше здоровье и ближайшие медицинские события',button('＋ Записаться на приём','primary','home-book'))+'<div class="grid metrics">'+defs.map(([code,ic,bg,label])=>{const m=lookup[code]||{};return '<article class="card metric"><div class="metric-top"><span>'+label+'</span><span class="metric-icon" style="background:'+bg+'">'+ic+'</span></div><strong>'+formatMetric(m.value)+' <small>'+esc(m.unit||'')+'</small></strong><small>Последнее измерение</small></article>'}).join('')+'</div><div class="grid home-top"><article class="panel home-chart"><div class="panel-head"><div><h2>Динамика показателей</h2><p>История за выбранный период</p></div><div class="periods">'+[[7,'7 дней'],[30,'30 дней'],[90,'90 дней']].map(([n,l])=>'<button data-days="'+n+'" class="'+(days===n?'active':'')+'">'+l+'</button>').join('')+'</div></div><div class="chart">'+chartSvg(analytics.series)+'</div><div class="chart-legend">'+analytics.series.filter(x=>['pulse','spo2','temperature','steps'].includes(x.code)).map(x=>'<button data-series="'+x.code+'" class="'+(chartVisible[x.code]===false?'muted-series':'')+'"><i style="--series:'+seriesColor(x.code)+'"></i>'+esc(x.label)+'</button>').join('')+'</div></article><article class="panel recent-panel"><div class="panel-head"><div><h2>Последние записи</h2><p>История визитов</p></div><button class="secondary" data-view="appointments">Все визиты ›</button></div>'+(recent.map(a=>visitMini(a,user.role)).join('')||'<div class="empty-state">История визитов появится здесь.</div>')+'</article><article class="panel assistant-preview"><div class="panel-head"><div><h2>ИИ-ассистент</h2><p>Справочная помощь</p></div><button class="secondary" data-view="assistant">Открыть чат ›</button></div><div class="assistant-teaser"><span>✳</span><div><b>Есть вопрос?</b><p>Обсудите общие вопросы о показателях, анализах и здоровых привычках.</p></div></div><button class="primary" data-view="assistant">Задать вопрос</button><p class="disclaimer">Ответы не заменяют медицинскую консультацию.</p></article></div><div class="grid home-bottom"><article class="panel health-panel"><div class="panel-head"><div><h2>Анализ здоровья</h2><p>Учебные статусы по последним показателям</p></div><button class="secondary" data-view="metrics">Показатели ›</button></div>'+healthSystems(d.metrics)+'</article><article class="panel upcoming-panel"><div class="panel-head"><div><h2>Ближайшие визиты</h2><p>Предстоящие медицинские мероприятия</p></div><button class="secondary" data-view="appointments">Все ›</button></div>'+(upcoming.map(a=>visitMini(a,user.role,true)).join('')||'<div class="empty-state"><span class="empty-icon">▣</span><b>Плановых визитов нет</b><button class="primary" data-view="appointments">Найти врача</button></div>')+'</article><article class="panel mini-map-panel"><div class="panel-head"><div><h2>География и доступность</h2><p>Медицинские организации рядом</p></div><button class="secondary" data-view="clinics">Все ›</button></div>'+(clinic?'<div class="mini-map"><iframe title="Карта клиник" loading="lazy" src="https://www.openstreetmap.org/export/embed.html?bbox=37.54%2C55.73%2C37.66%2C55.81&layer=mapnik&marker='+clinic.latitude+'%2C'+clinic.longitude+'"></iframe></div><b>'+esc(clinic.name)+'</b><p class="muted">'+esc(clinic.address)+'</p><button class="secondary" data-view="clinics">Открыть карту</button>':'<p class="muted">Клиники не добавлены.</p>')+'</article><article class="panel recs-panel"><div class="panel-head"><div><h2>Рекомендации</h2><p>Персональные полезные привычки</p></div><button class="secondary" data-view="recommendations">Все ›</button></div>'+(recsHtml||'<p class="muted">Рекомендаций пока нет.</p>')+'</article></div>'}
function healthSystems(metrics){const by=Object.fromEntries(metrics.map(x=>[x.code,x]));const status=(m,min,max)=>m?.value==null?'Недостаточно данных':Number(m.value)<min||Number(m.value)>max?'Требует внимания':'В норме';const rows=[['Сердечно-сосудистая система',status(by.pulse,50,110),'♥'],['Дыхательная система',status(by.spo2,95,100),'◉'],['Обмен веществ','Недостаточно данных','◇'],['Желудочно-кишечный тракт','Недостаточно данных','＋'],['Опорно-двигательный аппарат',status(by.steps,1000,50000),'↗']];return '<div class="health-analysis"><svg class="body-map" viewBox="0 0 110 220" role="img" aria-label="Схема систем организма"><circle cx="55" cy="22" r="15"/><path d="M42 42 Q55 35 68 42 L77 105 L68 110 L72 155 L65 212 L53 212 L50 158 L46 212 L34 212 L39 155 L42 110 L33 105Z"/><path d="M41 51 L17 103 M69 51 L93 103"/><circle class="dot-heart" cx="56" cy="72" r="5"/><circle class="dot-lungs" cx="47" cy="83" r="4"/><circle class="dot-lungs" cx="64" cy="83" r="4"/><circle class="dot-body" cx="55" cy="109" r="4"/><circle class="dot-bones" cx="43" cy="160" r="4"/><circle class="dot-bones" cx="66" cy="160" r="4"/></svg><div class="system-list">'+rows.map(x=>'<div class="system-row"><span class="system-mark">'+x[2]+'</span><span><b>'+x[0]+'</b><small class="status '+(x[1]==='В норме'?'':x[1]==='Требует внимания'?'warning':'gray')+'">'+x[1]+'</small></span></div>').join('')+'</div></div><p class="disclaimer">Оценка демонстрационная и не является диагнозом. При недостатке данных показывается соответствующий статус.</p>'}
function visitMini(a,role='patient',compact=false){const dt=new Date(a.starts_at),person=role==='doctor'?(a.patient||'Пациент'):(a.doctor||'Специалист');return '<div class="visit-mini"><span class="visit-avatar">'+(role==='doctor'?'♙':'✚')+'</span><span class="visit-copy"><b>'+esc(a.specialty||person)+'</b><small>'+esc(person)+' · '+dt.toLocaleDateString('ru-RU',{day:'numeric',month:'short'})+', '+dt.toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})+'</small></span><span class="status '+(a.status==='Завершена'?'gray':'')+'">'+esc(a.status)+'</span>'+(compact&&role==='patient'&&!['Отменена','Завершена'].includes(a.status)?'<button class="secondary" data-reschedule="'+a.id+'" data-start="'+esc(a.starts_at)+'" data-status="'+esc(a.status)+'">Перенести</button>':'')+'</div>'}
function seriesColor(code){return({pulse:'#438be4',spo2:'#19ad83',temperature:'#f0a647',steps:'#8b68df'})[code]||'#718294'}function chartSvg(series){const active=series.filter(x=>['pulse','spo2','temperature','steps'].includes(x.code)&&chartVisible[x.code]!==false);let paths='';for(const item of active){const points=item.points.map(p=>Number(p.value));if(!points.length)continue;const min=Math.min(...points),max=Math.max(...points),range=max-min||1;paths+='<polyline fill="none" stroke="'+seriesColor(item.code)+'" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" points="'+points.map((v,i)=>(i*100/(points.length-1||1))+','+(90-(v-min)/range*68)).join(' ')+'"/>'}return '<svg viewBox="0 0 100 100" preserveAspectRatio="none"><path d="M0 15H100M0 38H100M0 62H100M0 85H100" stroke="#edf1f4" stroke-width=".7"/>'+paths+'</svg>'}
async function metricsView(){const d=await api('/metrics?days='+days);const agg=await api('/analytics?days='+days);const stats=agg.series;return head('Мои показатели','История физиологических параметров за выбранный период',button('＋ Новое измерение','primary','add-measure'))+'<article class="panel"><div class="panel-head"><h2>Период</h2><div class="periods">'+[[1,'Сегодня'],[7,'7 дней'],[30,'30 дней'],[90,'90 дней']].map(([n,l])=>'<button data-days="'+n+'" class="'+(days===n?'active':'')+'">'+l+'</button>').join('')+'</div></div><div class="grid metrics">'+stats.map(s=>'<div class="stat"><small>'+esc(s.label)+'</small><b>'+s.average+' '+esc(s.unit)+'</b><small>среднее · min '+s.minimum+' · max '+s.maximum+'</small></div>').join('')+'</div></article><article class="panel" style="margin-top:14px"><div class="panel-head"><h2>История измерений</h2><span class="status">'+d.length+' записей</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Показатель</th><th>Значение</th><th>Дата и время</th><th>Источник</th><th></th></tr></thead><tbody>'+d.map(x=>'<tr><td>'+esc(x.label)+'</td><td><b>'+esc(x.value)+' '+esc(x.unit)+'</b></td><td>'+new Date(x.measured_at).toLocaleString('ru-RU')+'</td><td>'+esc(x.source)+'</td><td><button class="secondary" data-edit-measure="'+x.id+'">Изменить</button><button class="danger" data-delete-measure="'+x.id+'">Удалить</button></td></tr>').join('')+'</tbody></table></div></article>'}
async function appointmentsView(){if(user.role==='admin')return head('Записи к врачу','Администратор может настраивать расписания специалистов в разделе «Настройки»',button('Настроить расписания','primary','go-settings'))+'<article class="panel empty-state"><span class="empty-icon">▣</span><b>Медицинские записи скрыты для администратора</b><p>Откройте настройки, чтобы управлять специалистами и их расписанием без просмотра данных пациентов.</p></article>';const [all,docs]=await Promise.all([api('/appointments'),api('/doctors')]);cache.doctors=docs;const active=all.filter(x=>!['Завершена','Отменена'].includes(x.status)),history=all.filter(x=>['Завершена','Отменена'].includes(x.status));const isPatient=user.role==='patient';return head(isPatient?'Записи к врачу':'Расписание приёмов',isPatient?'Найдите специалиста, запишитесь или перенесите визит.':'Приёмы пациентов, которым предоставлен доступ к медицинским данным.',isPatient?button('＋ Записаться на приём','primary','book-appointment'):'')+'<div class="grid appointment-overview"><article class="stat"><small>Предстоящие</small><b>'+active.length+'</b><small>активных записей</small></article><article class="stat"><small>История</small><b>'+history.length+'</b><small>прошлых и отменённых</small></article><article class="stat"><small>Часы приёма</small><b>09:00–17:00</b><small>свободное время в расписании врача</small></article></div><article class="panel"><div class="panel-head"><div><h2>'+(isPatient?'Ближайшие визиты':'Пациенты и записи')+'</h2><p>'+all.length+' записей всего</p></div>'+(user.role==='doctor'?'<button class="secondary" data-view="settings">Моё расписание</button>':'')+'</div>'+(active.length?active.map(a=>'<div class="appointment-row">'+visitMini(a,user.role,true)+(isPatient?'<div class="appointment-actions"><button class="secondary" data-reschedule="'+a.id+'" data-start="'+esc(a.starts_at)+'" data-status="'+esc(a.status)+'">Перенести</button><button class="danger" data-cancel="'+a.id+'">Отменить</button><button class="secondary" data-delete-appointment="'+a.id+'">Удалить из списка</button></div>':user.role==='doctor'?'<div class="appointment-actions"><button class="primary" data-complete-appointment="'+a.id+'">Отметить приём состоявшимся</button>'+(a.patient_id?'<button class="secondary" data-patient-records="'+a.patient_id+'">Медкарта пациента</button>':'')+'</div>':'')+'</div>').join(''):'<div class="empty-state"><span class="empty-icon">▣</span><b>Предстоящих визитов нет</b><p>'+(isPatient?'Выберите врача и подходящее свободное время.':'Записи появятся, когда пациент выберет время.')+'</p>'+(isPatient?'<button class="primary" id="book-empty">Записаться на приём</button>':'')+'</div>')+'</article><article class="panel" style="margin-top:14px"><div class="panel-head"><div><h2>История визитов</h2><p>Завершённые и отменённые приёмы</p></div></div>'+(history.length?history.map(a=>'<div class="appointment-row">'+visitMini(a,user.role)+'</div>').join(''):'<p class="muted">Прошлых визитов пока нет.</p>')+'</article>'+(isPatient?'<article class="panel" style="margin-top:14px"><div class="panel-head"><div><h2>Выберите специалиста</h2><p>Терапевт · кардиолог · эндокринолог</p></div><input id="doctor-search" placeholder="Поиск по имени или специальности"></div><div id="doctor-list">'+docs.map(doctorCard).join('')+'</div></article>':'')}
function doctorCard(d){return '<article class="doctor-card"><span class="doctor-avatar">'+esc(d.name.split(' ').map(x=>x[0]).slice(0,2).join(''))+'</span><span><b>'+esc(d.name)+'</b><p>'+esc(d.specialty)+' · стаж '+d.experience_years+' лет<br>'+esc(d.clinic)+'<br>'+esc(d.bio||'Приём по записи')+'</p></span>'+(user.role==='patient'?'<button class="primary" data-book="'+d.id+'">Записаться</button>':'')+'</article>'}
async function doctorsView(){const docs=await api('/doctors?search='+encodeURIComponent(sessionStorage.getItem('hh_search')||''));cache.doctors=docs;return head('Выбор специалиста','Выберите врача и свободное время приёма')+'<article class="panel"><div class="panel-head"><h2>Врачи</h2><input id="doctor-search" placeholder="Имя или специальность"></div><div id="doctor-list">'+docs.map(doctorCard).join('')+'</div></article>'}
async function labsView(){const labs=await api('/labs');const add=user.role==='patient'?button('＋ Добавить анализ','primary','add-lab'):'';return head('Анализы','Просматривайте результаты и добавляйте личные записи',add)+'<div class="toolbar"><button class="secondary" data-lab-filter="all">Все</button><button class="secondary" data-lab-filter="past">Прошлые</button></div><div class="grid labs-grid" id="labs-grid">'+labs.map(l=>'<article class="lab-card" data-date="'+l.taken_on+'"><div class="panel-head"><b>'+esc(l.name)+'</b><span class="status">'+esc(l.status)+'</span></div><p>'+new Date(l.taken_on).toLocaleDateString('ru-RU')+' · '+esc(l.clinic||'Клиника')+'</p>'+l.results.map(r=>'<div class="result-line"><span>'+esc(r.name)+'</span><strong style="color:'+(r.value<r.min||r.value>r.max?'#db646e':'#33485a')+'">'+r.value+' '+esc(r.unit)+' <small>('+r.min+'–'+r.max+')</small></strong></div>').join('')+(user.role==='patient'?'<div class="card-actions"><button class="danger" data-delete-lab="'+l.id+'">Удалить запись</button></div>':'')+'</article>').join('')+'</div>'+(labs.length?'':'<div class="panel empty-state"><span class="empty-icon">▤</span><b>Результатов пока нет</b><p>Добавьте запись об анализе, чтобы она появилась здесь.</p></div>')}
async function recordsView(){const r=await api('/records');const add=user.role==='patient'?button('＋ Добавить запись','primary','add-record'):'';return head('Медицинская карта','Храните личные заметки и просматривайте историю',add)+'<div class="toolbar">'+['Все','Заключения врачей','Результаты анализов','Вакцинация','Аллергии','Хронические заболевания','Другое'].map(x=>'<button class="secondary" data-record-filter="'+x+'">'+x+'</button>').join('')+'</div><div id="record-list">'+r.map(x=>'<article class="record-card" data-type="'+esc(x.record_type)+'"><span class="line-icon" style="background:#edf4ff">▧</span><span class="record-copy"><b>'+esc(x.title)+'</b><p>'+esc(x.record_type)+' · '+new Date(x.created_at).toLocaleDateString('ru-RU')+'<br>'+esc(x.description)+'</p></span>'+(user.role==='patient'?'<button class="danger" data-delete-record="'+x.id+'">Удалить</button>':'')+'</article>').join('')+'</div>'+(r.length?'':'<article class="panel empty-state"><span class="empty-icon">▧</span><b>Медицинская карта пока пуста</b><p>Добавьте личную заметку или важную информацию.</p></article>')}
async function notificationsView(){const a=await api('/notifications');return head('Уведомления','События, связанные с вашими медицинскими данными')+'<article class="panel">'+a.map(n=>'<div class="notify '+(!n.is_read?'unread':'')+'"><span>♢</span><span><b>'+esc(n.title)+'</b><p>'+esc(n.body)+'</p></span><small>'+new Date(n.created_at).toLocaleDateString('ru-RU')+'</small>'+(!n.is_read?'<button class="secondary" data-read="'+n.id+'">Прочитано</button>':'')+'</div>').join('')+(a.length?'':'<p class="muted">Новых уведомлений нет.</p>')+'</article>'}
async function recommendationsView(){const a=await api('/recommendations');const add=user.role==='patient'?button('＋ Добавить рекомендацию','primary','add-recommendation'):'';return head('Рекомендации','Отмечайте выполнение и добавляйте личные цели',add)+'<div class="recommendation-list">'+a.map(r=>'<article class="recommendation"><span class="line-icon" style="background:#e8f8f1;color:#159c72">✦</span><span style="flex:1"><b>'+esc(r.title)+'</b><p>'+esc(r.description)+'<br><small>Основание: '+esc(r.basis||'личная рекомендация')+'</small></p><span class="status">'+esc(r.status)+'</span></span>'+(r.status!=='Выполнена'?'<button class="secondary" data-rec="'+r.id+'">Отметить выполненной</button>':'')+(r.is_custom?'<button class="danger" data-delete-rec="'+r.id+'">Удалить</button>':'')+'</article>').join('')+'</div>'+(a.length?'':'<article class="panel empty-state"><span class="empty-icon">✦</span><b>Пока нет рекомендаций</b><p>Добавьте личную цель или привычку.</p></article>')}
function assistantView(){return head('ИИ-ассистент','Справочная информация о показателях и здоровых привычках')+'<article class="panel"><div class="chat" id="chat"><div class="bubble">Здравствуйте! Могу помочь с общей справочной информацией. Я не ставлю диагнозы и не назначаю лечение.</div></div><div class="quick">'+['Что означают мои анализы?','Питание при дефиците витамина D','Упражнения для сердца','Рекомендации по сну'].map(x=>'<button data-prompt="'+x+'">'+x+'</button>').join('')+'</div><form class="chat-form" id="chat-form"><input name="message" placeholder="Напишите вопрос…" required><button class="primary">Отправить</button></form><label class="consent"><input type="checkbox" id="chat-consent"> Сохранять историю переписки в приложении</label><p class="disclaimer">Ответы учебного ассистента — справочные и не являются медицинской консультацией. При опасных симптомах обратитесь за неотложной помощью.</p></article>'}
async function clinicsView(){const a=await api('/clinics');cache.clinics=a;const first=a[0];return head('География и доступность','Найдите клинику, посмотрите контакты и постройте маршрут')+'<article class="panel"><div class="panel-head"><div><h2>Карта медицинских организаций</h2><p>Выберите клинику, чтобы открыть маршрут и контакты</p></div><input id="clinic-search" placeholder="Поиск по названию или адресу"></div>'+(first?'<div class="large-map"><iframe title="Интерактивная карта OpenStreetMap" src="https://www.openstreetmap.org/export/embed.html?bbox=37.50%2C55.70%2C37.70%2C55.83&layer=mapnik&marker='+first.latitude+'%2C'+first.longitude+'" loading="lazy"></iframe></div>':'<div class="empty-state">Клиники пока не добавлены.</div>')+'<div id="clinic-list">'+a.map((c,i)=>'<article class="clinic-card" data-clinic-name="'+esc((c.name+' '+c.address).toLowerCase())+'"><span class="line-icon">⌖</span><span><b>'+esc(c.name)+'</b><p>'+esc(c.address)+' · '+esc(c.phone)+'<br>'+esc(c.hours)+'</p></span><a class="primary" target="_blank" rel="noopener" href="https://www.openstreetmap.org/directions?from=&to='+c.latitude+'%2C'+c.longitude+'">Построить маршрут</a></article>').join('')+'</div></article>'}
async function reportView(){const a=await api('/analytics?days='+days);return head('Отчёт о здоровье','Сводная статистика за выбранный период',button('Скачать CSV','primary','download-report'))+'<article class="panel"><div class="panel-head"><h2>Период наблюдения</h2><div class="periods">'+[7,30,90].map(n=>'<button data-days="'+n+'" class="'+(days===n?'active':'')+'">'+n+' дней</button>').join('')+'</div></div><div class="stat-grid">'+a.series.map(x=>'<div class="stat"><small>'+esc(x.label)+' ('+esc(x.unit)+')</small><b>'+x.average+'</b><small>среднее · минимум '+x.minimum+' · максимум '+x.maximum+'</small><small>'+x.count+' измерений</small></div>').join('')+'</div><button class="secondary" onclick="window.print()">Печать отчёта</button></article>'}
function scheduleMarkup(rows,doctorId=''){const map=Object.fromEntries(rows.map(x=>[x.weekday,x]));return '<form id="schedule-form" class="schedule-form" data-doctor="'+doctorId+'"><div class="schedule-days">'+['Понедельник','Вторник','Среда','Четверг','Пятница','Суббота','Воскресенье'].map((label,i)=>{const d=map[i+1]||{};return '<div class="schedule-day"><label class="day-toggle"><input type="checkbox" name="day-'+(i+1)+'-active" '+(d.is_active?'checked':'')+'><b>'+label+'</b></label><label>С<input name="day-'+(i+1)+'-start" type="time" value="'+String(d.start_time||'09:00').slice(0,5)+'"></label><label>До<input name="day-'+(i+1)+'-end" type="time" value="'+String(d.end_time||'17:00').slice(0,5)+'"></label><label>Минут<select name="day-'+(i+1)+'-slot"><option '+(Number(d.slot_minutes||30)===15?'selected':'')+'>15</option><option '+(Number(d.slot_minutes||30)===30?'selected':'')+'>30</option><option '+(Number(d.slot_minutes||30)===60?'selected':'')+'>60</option></select></label></div>'}).join('')+'</div><p class="form-hint">Укажите дни и часы работы. Система предложит посетителям только свободные интервалы.</p><button class="primary" type="submit">Сохранить расписание</button></form>'}
async function settingsView(){const profile=await api('/profile');if(user.role==='patient')return head('Настройки профиля','Управляйте контактными данными и личными настройками')+'<article class="panel settings-panel"><div class="panel-head"><div><h2>Личные данные</h2><p>Изменения сохраняются в профиле</p></div><span class="avatar large-avatar">'+esc(profile.name.split(' ').map(x=>x[0]).slice(0,2).join(''))+'</span></div><form id="profile-form" class="form two"><label>Имя и фамилия<input name="name" maxlength="140" value="'+esc(profile.name)+'" required></label><label>Email<input value="'+esc(profile.email)+'" disabled></label><label>Телефон<input name="phone" maxlength="40" value="'+esc(profile.phone||'')+'" placeholder="+7 900 000-00-00"></label><label>Дата рождения<input name="birth_date" type="date" value="'+(profile.birth_date?String(profile.birth_date).slice(0,10):'')+'"></label><label>Пол<select name="sex"><option '+(profile.sex==='Не указан'?'selected':'')+'>Не указан</option><option '+(profile.sex==='Женский'?'selected':'')+'>Женский</option><option '+(profile.sex==='Мужской'?'selected':'')+'>Мужской</option><option '+(profile.sex==='Другой'?'selected':'')+'>Другой</option></select></label><label>Группа крови<input value="'+esc(profile.blood_type||'Не указана')+'" disabled></label><div class="full"><button class="primary">Сохранить изменения</button></div></form></article><article class="panel settings-panel"><h2>Конфиденциальность</h2><p class="muted">Данные хранятся в учебной базе PostgreSQL. История переписки с ассистентом сохраняется только при включённом согласии.</p><button class="secondary" data-view="report">Открыть отчёты о здоровье</button></article>';if(user.role==='doctor'){const rows=await api('/my-schedule');return head('Настройки врача','Управляйте доступностью для записи пациентов')+'<article class="panel"><div class="panel-head"><div><h2>Моё расписание</h2><p>Шаг слота определяет время, доступное для записи</p></div></div>'+scheduleMarkup(rows)+'</article><article class="panel settings-panel"><h2>Доступ к медицинской карте</h2><p class="muted">К пациентам доступны только данные, для которых пациент выдал учебное разрешение.</p></article>'}const [summary,accounts,clinics,specialties]=await Promise.all([api('/admin/summary'),api('/admin/users'),api('/clinics'),api('/specialties')]);cache.admin={accounts,clinics,specialties};const doctors=accounts.filter(x=>x.role==='doctor'&&x.is_active);let schedule='';if(doctors.length){const pick=Number($('#schedule-doctor')?.value)||doctors[0].doctor_id;const rows=await api('/my-schedule?doctor_id='+pick);schedule='<div class="panel-head"><h2>Расписание врача</h2><select id="schedule-doctor">'+doctors.map(x=>'<option value="'+x.doctor_id+'" '+(Number(x.doctor_id)===pick?'selected':'')+'>'+esc(x.name)+' · '+esc(x.specialty||'Специалист')+'</option>').join('')+'</select></div>'+scheduleMarkup(rows,pick)}return head('Настройки системы','Администрирование аккаунтов, расписаний и клиник')+'<div class="grid metrics admin-metrics">'+[['Пользователи',accounts.length],['Врачи',summary.doctors],['Клиники',summary.clinics],['Визиты',summary.appointments]].map(x=>'<article class="stat"><small>'+x[0]+'</small><b>'+x[1]+'</b></article>').join('')+'</div><article class="panel settings-panel">'+schedule+'</article><article class="panel settings-panel"><div class="panel-head"><div><h2>Учётные записи</h2><p>Администратор не открывает медицинские записи пациентов</p></div><button id="add-account" class="primary"><span class="add-icon">+</span>Новый аккаунт</button></div><div class="account-list">'+accounts.map(x=>'<div class="account-row"><span class="avatar">'+esc(x.name.split(' ').map(z=>z[0]).slice(0,2).join(''))+'</span><span><b>'+esc(x.name)+'</b><small>'+esc(x.email)+' · '+roleName(x.role)+(x.specialty?' · '+esc(x.specialty):'')+'</small></span><span class="status '+(x.is_active?'':'gray')+'">'+(x.is_active?'Активен':'Отключён')+'</span>'+(x.id!==user.id?'<button class="secondary" data-account="'+x.id+'" data-active="'+x.is_active+'">'+(x.is_active?'Отключить':'Включить')+'</button>':'')+'</div>').join('')+'</div></article><article class="panel settings-panel"><div class="panel-head"><div><h2>Медицинские организации</h2><p>Контакты и точки на карте</p></div><button id="add-clinic" class="primary"><span class="add-icon">+</span>Добавить клинику</button></div>'+clinics.map(c=>'<div class="clinic-admin-row"><span><b>'+esc(c.name)+'</b><small>'+esc(c.address)+' · '+esc(c.phone||'')+'</small></span><button class="secondary" data-edit-clinic="'+c.id+'">Изменить</button><button class="danger" data-delete-clinic="'+c.id+'">Удалить</button></div>').join('')+'</article><article class="panel settings-panel"><div class="panel-head"><div><h2>Добавить пользователя</h2><p>Создайте учебную учётную запись пациента или врача</p></div></div><form id="account-form" class="form two"><label>ФИО<input name="name" maxlength="140" required></label><label>Email<input name="email" type="email" required></label><label>Пароль<input name="password" type="password" minlength="8" required></label><label>Роль<select name="role" id="account-role"><option value="patient">Пациент</option><option value="doctor">Врач</option></select></label><label class="doctor-field" hidden>Клиника<select name="clinic_id">'+clinics.map(c=>'<option value="'+c.id+'">'+esc(c.name)+'</option>').join('')+'</select></label><label class="doctor-field" hidden>Специальность<select name="specialty_id">'+specialties.map(c=>'<option value="'+c.id+'">'+esc(c.name)+'</option>').join('')+'</select></label><label class="doctor-field" hidden>Стаж, лет<input name="experience_years" type="number" min="0" max="60" value="0"></label><div class="full"><button class="primary">Создать аккаунт</button></div></form></article>'}
async function searchView(){const term=sessionStorage.getItem('hh_search')||'';const jobs=[api('/doctors?search='+encodeURIComponent(term)),user.role==='admin'?Promise.resolve([]):api('/labs?search='+encodeURIComponent(term)),user.role==='admin'?Promise.resolve([]):api('/records?search='+encodeURIComponent(term))];const [docs,labs,records]=await Promise.all(jobs.map(x=>x.catch(()=>[])));cache.doctors=docs;return head('Результаты поиска','По запросу «'+esc(term)+'»')+'<div class="grid search-grid"><article class="panel"><h2>Врачи</h2>'+(docs.map(doctorCard).join('')||'<p class="muted">Совпадений нет.</p>')+'</article><article class="panel"><h2>Анализы</h2>'+(labs.map(x=>'<button class="search-result" data-lab-detail="'+x.id+'"><b>'+esc(x.name)+'</b><small>'+new Date(x.taken_on).toLocaleDateString('ru-RU')+' · '+esc(x.status)+'</small></button>').join('')||'<p class="muted">Совпадений нет.</p>')+'</article><article class="panel"><h2>Медкарта</h2>'+(records.map(x=>'<button class="search-result" data-record-detail="'+x.id+'"><b>'+esc(x.title)+'</b><small>'+esc(x.record_type)+' · '+new Date(x.created_at).toLocaleDateString('ru-RU')+'</small></button>').join('')||'<p class="muted">Совпадений нет.</p>')+'</article></div>'}
async function bindView(){
$$('#view-root [data-view]').forEach(b=>b.onclick=()=>go(b.dataset.view));
if(view==='dashboard'||view==='metrics'){$$('#view-root [data-days]').forEach(b=>b.onclick=()=>{days=Number(b.dataset.days);renderView()});$('#add-measure')?.addEventListener('click',measureDialog);$('#find-doctor')?.addEventListener('click',()=>go('appointments'));if(view==='metrics'){$$('[data-edit-measure]').forEach(b=>b.onclick=()=>openForm('Изменить измерение','<label>Новое значение<input name="value" type="number" step="0.01" value="'+esc(b.closest('tr').querySelector('td:nth-child(2) b').textContent.trim().split(' ')[0])+'" required></label><label>Комментарий<textarea name="comment" maxlength="300" rows="3"></textarea></label>',async f=>{await api('/metrics/'+b.dataset.editMeasure,{method:'PUT',body:JSON.stringify({value:Number(f.value),comment:f.comment})});toast('Измерение обновлено');renderView()}));$$('[data-delete-measure]').forEach(b=>b.onclick=async()=>{if(!confirm('Удалить это измерение?'))return;try{await api('/metrics/'+b.dataset.deleteMeasure,{method:'DELETE'});toast('Измерение удалено');renderView()}catch(e){toast(e.message)}})}}
if(view==='appointments'||view==='doctors'){const search=$('#doctor-search');search?.addEventListener('input',async()=>{try{const a=await api('/doctors?search='+encodeURIComponent(search.value));$('#doctor-list').innerHTML=a.map(doctorCard).join('');bindBook()}catch(e){toast(e.message)}});bindBook();$('#book-appointment')?.addEventListener('click',()=>bookDialog());$$('[data-reschedule]').forEach(b=>b.onclick=()=>openForm('Перенести приём','<label>Новая дата и время<input name="starts_at" type="datetime-local" min="'+localDateTime(new Date())+'" value="'+localDateTime(b.dataset.start)+'" required></label><p class="form-hint">Можно выбрать только будущее свободное время.</p>',async f=>{const starts_at=new Date(f.starts_at);if(starts_at<=new Date())throw Error('Выберите будущее время');await api('/appointments/'+b.dataset.reschedule,{method:'PATCH',body:JSON.stringify({status:b.dataset.status,starts_at:starts_at.toISOString()})});toast('Приём перенесён');renderView()}));$$('[data-delete-appointment]').forEach(b=>b.onclick=async()=>{if(!confirm('Удалить эту запись на приём?'))return;try{await api('/appointments/'+b.dataset.deleteAppointment,{method:'DELETE'});toast('Запись удалена');renderView()}catch(e){toast(e.message)}});$$('[data-cancel]').forEach(b=>b.onclick=async()=>{try{await api('/appointments/'+b.dataset.cancel,{method:'PATCH',body:JSON.stringify({status:'Отменена'})});toast('Запись отменена');renderView()}catch(e){toast(e.message)}});$('#find-doctor')?.addEventListener('click',()=>go('doctors'))}
if(view==='labs'){$$('[data-lab-filter]').forEach(b=>b.onclick=()=>$$('[data-date]').forEach(card=>card.hidden=b.dataset.labFilter==='past'&&new Date(card.dataset.date)>new Date()));$('#add-lab')?.addEventListener('click',()=>openForm('Добавить результат анализа','<label>Название анализа<input name="name" maxlength="180" placeholder="Например, общий анализ крови" required></label><label>Показатель<input name="result_name" maxlength="120" placeholder="Например, гемоглобин" required></label><div class="form two"><label>Значение<input name="value" type="number" step="0.001" required></label><label>Единица измерения<input name="unit" maxlength="40" placeholder="г/л" required></label><label>Нижняя граница нормы<input name="reference_min" type="number" step="0.001"></label><label>Верхняя граница нормы<input name="reference_max" type="number" step="0.001"></label></div><label>Дата анализа<input name="taken_on" type="date" value="'+new Date().toISOString().slice(0,10)+'" required></label><p class="form-hint">Вводите результат с бланка лаборатории. Это личная запись и не медицинское заключение.</p>',async f=>{await api('/labs',{method:'POST',body:JSON.stringify({...f,value:Number(f.value)})});toast('Анализ добавлен');renderView()}));$$('[data-delete-lab]').forEach(b=>b.onclick=async()=>{if(!confirm('Удалить результат анализа?'))return;try{await api('/labs/'+b.dataset.deleteLab,{method:'DELETE'});toast('Анализ удалён');renderView()}catch(e){toast(e.message)}})}
if(view==='records'){$$('[data-record-filter]').forEach(b=>b.onclick=()=>$$('[data-type]').forEach(card=>card.hidden=b.dataset.recordFilter!=='Все'&&card.dataset.type!==b.dataset.recordFilter));$('#add-record')?.addEventListener('click',()=>openForm('Добавить запись в медкарту','<label>Тип записи<select name="record_type" required><option>Другое</option><option>Аллергии</option><option>Хронические заболевания</option><option>Вакцинация</option><option>Результаты анализов</option><option>Заключения врачей</option></select></label><label>Название<input name="title" maxlength="180" required></label><label>Описание<textarea name="description" maxlength="2000" rows="4" placeholder="Личная заметка или сведения для себя"></textarea></label><p class="form-hint">Добавленная запись помечается как личная заметка, она не является подтверждённым заключением врача.</p>',async f=>{await api('/records',{method:'POST',body:JSON.stringify(f)});toast('Запись добавлена в медкарту');renderView()}));$$('[data-delete-record]').forEach(b=>b.onclick=async()=>{if(!confirm('Удалить эту запись из медкарты?'))return;try{await api('/records/'+b.dataset.deleteRecord,{method:'DELETE'});toast('Запись удалена');renderView()}catch(e){toast(e.message)}})}
if(view==='notifications')$$('[data-read]').forEach(b=>b.onclick=async()=>{try{await api('/notifications/'+b.dataset.read+'/read',{method:'PATCH'});renderView()}catch(e){toast(e.message)}});
if(view==='recommendations'){$$('[data-rec]').forEach(b=>b.onclick=async()=>{try{await api('/recommendations/'+b.dataset.rec,{method:'PATCH',body:JSON.stringify({status:'Выполнена'})});toast('Рекомендация отмечена выполненной');renderView()}catch(e){toast(e.message)}});$('#add-recommendation')?.addEventListener('click',()=>openForm('Добавить личную цель','<label>Название<input name="title" maxlength="180" placeholder="Например, прогулка каждый день" required></label><label>Категория<input name="category" maxlength="60" value="Личное" required></label><label>Описание<textarea name="description" maxlength="1000" rows="3" required></textarea></label>',async f=>{await api('/recommendations',{method:'POST',body:JSON.stringify(f)});toast('Личная рекомендация добавлена');renderView()}));$$('[data-delete-rec]').forEach(b=>b.onclick=async()=>{if(!confirm('Удалить личную цель?'))return;try{await api('/recommendations/'+b.dataset.deleteRec,{method:'DELETE'});toast('Цель удалена');renderView()}catch(e){toast(e.message)}})}
if(view==='assistant'){const send=async text=>{const c=$('#chat');c.insertAdjacentHTML('beforeend','<div class="bubble me">'+esc(text)+'</div>');try{const r=await api('/assistant',{method:'POST',body:JSON.stringify({message:text,consent:$('#chat-consent')?.checked===true})});c.insertAdjacentHTML('beforeend','<div class="bubble">'+esc(r.answer)+'</div>')}catch(e){toast(e.message)}c.scrollTop=c.scrollHeight};$('#chat-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);send(f.get('message'));e.currentTarget.reset()};$$('[data-prompt]').forEach(b=>b.onclick=()=>send(b.dataset.prompt))}
if(view==='report'){$$('#view-root [data-days]').forEach(b=>b.onclick=()=>{days=Number(b.dataset.days);renderView()});$('#download-report').onclick=async()=>{try{const r=await fetch('/api/report.csv?days='+days,{headers:{Authorization:'Bearer '+token}});if(!r.ok)throw Error('Не удалось скачать отчёт');const blob=await r.blob();const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='healthhub-report.csv';a.click();URL.revokeObjectURL(a.href)}catch(e){toast(e.message)}}}
}
function bookingDate(){let d=new Date(Date.now()+86400000);for(let i=0;i<8;i++){const k=dateOnly(d),weekday=new Date(k+'T12:00:00Z').getUTCDay();if(weekday!==0)return k;d.setDate(d.getDate()+1)}return dateOnly(d)}
async function loadSlots(doctorId,date,select){select.innerHTML='<option value="">Загружаю свободное время…</option>';try{const slots=await api('/doctors/'+doctorId+'/slots?date='+encodeURIComponent(date));select.innerHTML=slots.length?'<option value="">Выберите время</option>'+slots.map(x=>'<option value="'+x.starts_at+'">'+x.time+'</option>').join(''):'<option value="">Свободных слотов нет</option>'}catch(e){select.innerHTML='<option value="">Не удалось загрузить время</option>';toast(e.message)}}
function bookDialog(doctorId){if(!cache.doctors?.length){api('/doctors').then(d=>{cache.doctors=d;bookDialog(doctorId)}).catch(e=>toast(e.message));return}const doctors=cache.doctors,specialties=[...new Set(doctors.map(x=>x.specialty))],initial=doctors.find(x=>Number(x.id)===Number(doctorId))||doctors[0],chosenSpecialty=initial.specialty;openForm('Запись на приём','<label>Специальность<select id="book-specialty">'+specialties.map(x=>'<option '+(x===chosenSpecialty?'selected':'')+'>'+esc(x)+'</option>').join('')+'</select></label><label>Врач<select name="doctor_id" id="book-doctor" required>'+doctors.filter(x=>x.specialty===chosenSpecialty).map(x=>'<option value="'+x.id+'" '+(Number(x.id)===Number(initial.id)?'selected':'')+'>'+esc(x.name)+' · '+esc(x.clinic)+'</option>').join('')+'</select></label><label>Дата<input type="date" id="book-date" min="'+dateOnly(new Date())+'" value="'+bookingDate()+'" required></label><label>Свободное время<select name="starts_at" id="book-time" required><option value="">Выберите время</option></select></label><label>Кратко опишите причину обращения<textarea name="reason" maxlength="500" rows="3" placeholder="Необязательно"></textarea></label><p class="form-hint">Слоты показаны по расписанию врача. Занятое время нельзя выбрать.</p>',async f=>{if(!f.starts_at)throw Error('Сначала выберите свободное время');await api('/appointments',{method:'POST',body:JSON.stringify({doctor_id:Number(f.doctor_id),starts_at:f.starts_at,reason:f.reason})});toast('Запись создана');go('appointments')});const form=$('#action-dialog form'),spec=form.querySelector('#book-specialty'),doc=form.querySelector('#book-doctor'),date=form.querySelector('#book-date'),time=form.querySelector('#book-time');const updateDocs=()=>{const list=doctors.filter(x=>x.specialty===spec.value);doc.innerHTML=list.map(x=>'<option value="'+x.id+'">'+esc(x.name)+' · '+esc(x.clinic)+'</option>').join('');refresh()};const refresh=()=>{if(doc.value&&date.value)loadSlots(doc.value,date.value,time)};spec.onchange=updateDocs;doc.onchange=refresh;date.onchange=refresh;refresh()}
function rescheduleDialog(button){const doctorId=button.dataset.doctor;if(!doctorId){toast('Не удалось определить врача для переноса');return}const initialDate=dateOnly(new Date(button.dataset.start));openForm('Перенести приём','<label>Новая дата<input type="date" id="move-date" min="'+dateOnly(new Date())+'" value="'+initialDate+'" required></label><label>Свободное время<select name="starts_at" id="move-time" required><option value="">Выберите время</option></select></label><p class="form-hint">После сохранения дата обновится в расписании пациента и врача.</p>',async f=>{if(!f.starts_at)throw Error('Выберите свободный слот');await api('/appointments/'+button.dataset.reschedule,{method:'PATCH',body:JSON.stringify({status:button.dataset.status,starts_at:f.starts_at})});toast('Время приёма перенесено');renderView()});const form=$('#action-dialog form'),date=form.querySelector('#move-date'),time=form.querySelector('#move-time'),refresh=()=>loadSlots(doctorId,date.value,time);date.onchange=refresh;refresh()}
function bindBook(){$$('[data-book]').forEach(b=>b.onclick=()=>bookDialog(Number(b.dataset.book)))}
function measureDialog(){openForm('Новое измерение','<label>Показатель<select name="code" required><option value="pulse">Пульс</option><option value="spo2">Насыщение кислородом</option><option value="temperature">Температура</option><option value="steps">Шаги</option><option value="sleep">Сон</option></select></label><label>Значение<input name="value" type="number" step="0.01" required></label><label>Дата и время<input name="measured_at" type="datetime-local" value="'+localDateTime()+'" required></label><label>Комментарий<textarea name="comment" maxlength="300" rows="3" placeholder="Необязательно"></textarea></label>',async f=>{await api('/metrics',{method:'POST',body:JSON.stringify({...f,value:Number(f.value),measured_at:new Date(f.measured_at).toISOString()})});toast('Измерение добавлено');renderView()})}
function loginScreen(){$('#root').innerHTML='<section class="login-screen"><div class="login-card"><div class="logo">✚</div><p class="eyebrow">ВАШЕ ЗДОРОВЬЕ — В ФОКУСЕ</p><h1>HealthHub <span>AI</span></h1><p class="muted">Войдите в демонстрационный медицинский кабинет</p><form id="login-form"><label>Email<input type="email" name="email" value="patient@healthhub.local" required></label><label>Пароль<input type="password" name="password" value="patient123" required></label><button class="primary wide">Войти в кабинет</button></form><div class="demo-users"><button data-login="patient">Пациент</button><button data-login="doctor">Врач</button><button data-login="admin">Администратор</button></div><p class="tiny">Только вымышленные данные. Не использовать для медицинских решений.</p></div></section><div id="toast" class="toast"></div>';$('#login-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);await login(f.get('email'),f.get('password'))};$$('[data-login]').forEach(b=>b.onclick=()=>{const [email,password]=demo[b.dataset.login];login(email,password)})}
async function login(email,password){try{const r=await api('/auth/login',{method:'POST',body:JSON.stringify({email,password})});token=r.token;user=r.user;localStorage.setItem('hh_token',token);localStorage.setItem('hh_user',JSON.stringify(user));view='dashboard';shell()}catch(e){toast(e.message)}}
function logout(){token='';user=null;localStorage.removeItem('hh_token');localStorage.removeItem('hh_user');loginScreen()}
if(token&&user)shell();else loginScreen();
